def autocomplete_suggestions(words, queries):
    trie = {}
    WORDS = "$words"
    for word in sorted(words):
        node = trie
        node.setdefault(WORDS, []).append(word)
        for ch in word:
            node = node.setdefault(ch, {})
            node.setdefault(WORDS, []).append(word)

    result = []
    for q in queries:
        node = trie
        found = True
        for ch in q:
            if ch not in node:
                found = False
                break
            node = node[ch]
        result.append(list(node.get(WORDS, [])) if found else [])
    return result
